/**
 * The headless replay runner as one Node ES module (#528): `src/sim/node-replay.ts` bundled by
 * esbuild with the defines Vite gives the game, and the loader that runs it on a build's own
 * `PhysicsModule.wasm`.
 *
 *   - `vite build` writes `dist/sim/node-replay.mjs` (vite.config.ts `simBundle()`), so every
 *     archived build carries the TypeScript tick it shipped, next to its wasm;
 *   - `npm run verify:replay:node` bundles the working tree's source on the fly;
 *   - `services/replay-verifier` (`VERIFIER_RUNNER=node`) loads a build's bundle.
 *
 * `buildSimBundle` refuses a bundle that pulls in any `@babylonjs/*` module: the Node run must not
 * import the renderer, so a scoring path that reaches into a mesh fails the build, not a replay.
 */

import { createHash } from 'node:crypto'
import { mkdirSync, readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { build } from 'esbuild'

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')

export const SIM_ENTRY = path.join(repoRoot, 'src', 'sim', 'node-replay.ts')
/** Where a build keeps its bundle, relative to the dist directory. */
export const SIM_BUNDLE = path.join('sim', 'node-replay.mjs')

/** Module paths the Node runner must never contain. */
const FORBIDDEN = /(^|\/)node_modules\/@babylonjs\//

/**
 * Bundle the runner to `outfile`. `buildId` / `wasmSha256` are the build's (`__PACHINBALL_BUILD__`,
 * `__PACHINBALL_WASM_SHA256__`); `env` is `import.meta.env` as Vite would define it for production.
 * Resolves `{ inputs, bytes }`; throws when an input is a Babylon module.
 */
export async function buildSimBundle({ outfile, buildId = 'dev', wasmSha256 = null, env = {} }) {
  mkdirSync(path.dirname(outfile), { recursive: true })
  const importMetaEnv = { BASE_URL: '/', MODE: 'production', DEV: false, PROD: true, SSR: false, ...env }
  const result = await build({
    entryPoints: [SIM_ENTRY],
    outfile,
    bundle: true,
    platform: 'node',
    format: 'esm',
    target: 'node22',
    metafile: true,
    legalComments: 'none',
    logLevel: 'error',
    define: {
      __PACHINBALL_BUILD__: JSON.stringify(buildId),
      __PACHINBALL_WASM_SHA256__: JSON.stringify(wasmSha256),
      'import.meta.env': JSON.stringify(importMetaEnv),
    },
    banner: { js: `// Generated by scripts/lib/sim-bundle.mjs from src/sim/node-replay.ts (#528) — build ${buildId}. Do not edit.` },
  })
  const inputs = Object.keys(result.metafile.inputs)
  const forbidden = inputs.filter((p) => FORBIDDEN.test(p))
  if (forbidden.length) {
    throw new Error(
      `the headless replay runner imports Babylon (${forbidden.length} module(s), e.g. ${forbidden.slice(0, 3).join(', ')}): ` +
        'gameplay reached into a renderer type. Move that code out of the tick (see docs/HEADLESS_REPLAY.md).',
    )
  }
  const bytes = result.metafile.outputs[path.relative(process.cwd(), outfile)]?.bytes ?? null
  return { inputs: inputs.length, bytes }
}

/**
 * The Emscripten factory for the `PhysicsModule.js` / `.wasm` pair in `wasmDir`, as the runner's
 * `moduleFactory`. The shipped glue is built for the web (it fetches its `.wasm` and reads no
 * `Module` overrides), so the bytes are served to it through a `fetch` that answers only for
 * `PhysicsModule.wasm`, for the duration of the instantiation. With `expectSha256`, bytes that hash
 * differently are refused: a verifier replays on the binary its build declares, or not at all.
 */
export async function wasmModuleFactory(wasmDir, { expectSha256 = null } = {}) {
  const bytes = readFileSync(path.join(wasmDir, 'PhysicsModule.wasm'))
  const sha256 = createHash('sha256').update(bytes).digest('hex')
  if (expectSha256 && sha256 !== expectSha256) {
    throw new Error(`${wasmDir}/PhysicsModule.wasm hashes to ${sha256.slice(0, 12)}, expected ${expectSha256.slice(0, 12)}`)
  }
  const { default: factory } = await import(pathToFileURL(path.join(wasmDir, 'PhysicsModule.js')).href)
  return {
    sha256,
    moduleFactory: async () => {
      const realFetch = globalThis.fetch
      globalThis.fetch = async (input, init) => {
        const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url
        if (url.endsWith('PhysicsModule.wasm')) {
          return new Response(bytes, { headers: { 'Content-Type': 'application/wasm' } })
        }
        return realFetch(input, init)
      }
      try {
        return await factory()
      } finally {
        globalThis.fetch = realFetch
      }
    },
  }
}

/** `replayTapeInNode` from a bundle file. */
export async function loadSimBundle(file) {
  const mod = await import(pathToFileURL(path.resolve(file)).href)
  if (typeof mod.replayTapeInNode !== 'function') throw new Error(`${file} does not export replayTapeInNode`)
  return mod.replayTapeInNode
}
